  "legal.privacy.aChangeIsPublishedAsANewVersionWithItsOwnVersionNumberAn": "تبدیلی اپنے ورژن نمبر اور نافذ العمل تاریخ کے ساتھ نئے ورژن کے طور پر شائع ہوتی ہے۔ اہم تبدیلیاں نافذ ہونے سے پہلے آپ کو بتا دی جاتی ہیں، اور نافذ العمل تاریخ کے بعد سروس کا استعمال جاری رکھنے کا مطلب ہے کہ اپ ڈیٹ کی گئی پالیسی آپ کے اس وقت کے استعمال پر لاگو ہوگی۔ ہم نیا ورژن پرانے ورژن کے تحت قبول کی گئی شرائط پر پیچھے سے لاگو نہیں کریں گے۔",
  "legal.privacy.n15ChangesToThisPolicy": "15. اس پالیسی میں تبدیلیاں",
  "legal.privacy.rule8OfTheDpdpRulesImposesAFixedInactivitytriggeredErasu": "DPDP Rules کا Rule 8 بڑے ای کامرس اداروں، آن لائن گیمنگ انٹرمیڈیریز، اور تیسرے شیڈول میں درج سوشل میڈیا انٹرمیڈیریز پر ایک مقررہ، غیر سرگرمی پر مبنی ہٹانے کی مدت عائد کرتا ہے۔ SophionOS ان میں سے کوئی نہیں، اس لیے یہ مقررہ مدت آپ کے ورک اسپیس پر لاگو نہیں ہوتی، اور ہم اسے تب تک رکھتے ہیں جب تک آپ اسے یا اپنا اکاؤنٹ حذف نہ کریں۔ اگر ہم کبھی تیسرے شیڈول کے تحت آنے والے fiduciary بن جائیں تو ہم مقررہ مدت لاگو کریں گے اور Rule 8 کے مطابق ہٹانے سے کم از کم 48 گھنٹے پہلے آپ کو مطلع کریں گے۔",
  "legal.privacy.erasure": "ہٹانا۔",
  "legal.privacy.encryptionInTransitAndAtRestHashedApiKeysPeruserRowIsola": ": منتقلی اور ذخیرے میں خفیہ کاری، API کلیں ہیش شدہ، فی صارف سطر کی الگ تھلگ، اور ایک عالمی AI بند کرنے کا سوئچ۔ Rule 14 ہم سے شکایت کے طریقہ کار اور Grievance Officer کے رابطے کی تفصیلات شائع کرنے کا تقاضا کرتا ہے؛ سیکشن 9 وہ نوٹس ہے۔ Rule 15 بھارت سے باہر منتقلی کو کنٹرول کرتا ہے، جسے سیکشن 11 میں پیش کیا گیا ہے۔",
  "legal.privacy.whereTheDpdpRules2025ApplyRule6RequiresADataFiduciaryToT": "جہاں DPDP Rules، 2025 لاگو ہوتے ہیں، Rule 6 ایک Data Fiduciary سے کم از کم حفاظتی اقدامات کرنے کا مطالبہ کرتا ہے۔ ہم انہیں اگلے جدول کے مطابق پورا کرتے ہیں۔",
