  "legal.privacy.obtainASummaryOfThePersonalDataWeProcessAboutYouAndOfOur": ": آپ کے بارے میں ہم جو ذاتی ڈیٹا پروسیس کرتے ہیں اور ہماری پروسیسنگ کا خلاصہ حاصل کریں۔",
