  "legal.privacy.yourRightsAsADataPrincipal": "ایک Data Principal کی حیثیت سے آپ کے حقوق۔",
  "legal.privacy.weProcessYourPersonalDataOnlyOnTheBasisYouGiveUsWhenYouC": "ہم آپ کا ذاتی ڈیٹا صرف اُس بنیاد پر پروسیس کرتے ہیں جو آپ اکاؤنٹ بناتے وقت دیتے ہیں، یعنی آپ کی رضامندی، سروس فراہم کرنے کے لیے۔ یہ پالیسی وہ نوٹس ہے جو DPDP Rules تقاضا کرتے ہیں: بتاتی ہے کہ ہم کون سا ذاتی ڈیٹا اکٹھا کرتے ہیں، پروسیسنگ کے مقاصد، رضامندی کیسے واپس لیں، اور اپنے حقوق کیسے استعمال کریں یا شکایت کیسے کریں۔ آپ کسی بھی وقت رضامندی واپس لے سکتے ہیں، لیکن واپس لینے سے ہماری آپ کو سروس دینے کی صلاحیت ختم ہو جاتی ہے، کیونکہ ورک اسپیس کی پروسیسنگ ہی سروس ہے۔ رضامندی واپس لینے سے پہلے ہوئی پروسیسنگ متاثر نہیں ہوتی۔",
  "legal.privacy.consentAndNotice": "رضامندی اور نوٹس۔",
  "legal.privacy.forThePersonalDataYouGiveUsAndForTheWorkspaceContentYouC": "ہمیں دیے گئے ذاتی ڈیٹا اور یہاں آپ کی بنائی ہوئی ورک اسپیس کے مواد کے لیے۔ ہمارے سروس فراہم کرنے والے ہمارے Data Processors ہیں۔ Dodo Payments ایک استثناء ہے: merchant of record کی حیثیت سے وہ ادائیگی کا ڈیٹا اپنے حق میں Data Fiduciary کے طور پر رکھتے ہیں، ہمارے processor نہیں (سیکشن 4.1)۔ دیکھیں",
  "legal.privacy.dataFiduciary": "Data Fiduciary",
  "legal.privacy.tahaAalamASoleProprietorTradingAsSophionosIsThe": ". Taha Aalam، جو SophionOS کے نام سے تجارت کرنے والے ایک تنہا مالک ہیں، وہ",
  "legal.privacy.dataPrincipal": "Data Principal",
  "legal.privacy.youAreThe": "آپ",
  "legal.privacy.whoIsWho": "کون کون ہے۔",
  "legal.privacy.thisSectionAppliesIfYouAreInIndiaOrIfTheDigitalPersonalD": "یہ سیکشن آپ پر لاگو ہوتا ہے اگر آپ بھارت میں ہیں، یا اگر Digital Personal Data Protection Act, 2023 (\"DPDP Act\") اور Digital Personal Data Protection Rules, 2025 (\"DPDP Rules\") آپ کے ذاتی ڈیٹا کی ہماری پروسیسنگ پر کسی دوسری طرح سے لاگو ہوتے ہیں۔",
  "legal.privacy.n14NoticeToUsersInIndia": "14. بھارت کے صارفین کے لیے نوٹس",
  "legal.privacy.weWillVerifyYourIdentityAgainstYourAccountEmailAndRespon": ". ہم آپ کی اکاؤنٹ ای میل سے شناخت تصدیق کریں گے اور قابلِ اطلاق قانون کی مقررہ مدت میں جواب دیں گے۔ جہاں آپ کی ریاست اجازت دے، آپ کسی مجاز ایجنٹ کو استعمال کر سکتے ہیں۔",
  "legal.privacy.toExerciseARightEmail": "کسی حق کو استعمال کرنے کے لیے، ای میل کریں",
  "legal.privacy.categoriesCollectedInTheLast12MonthsIdentifiersEmailName": "پچھلے 12 مہینوں میں اکٹھی کی گئی اقسام: شناساگر (ای میل، نام، اکاؤنٹ id)، انٹرنیٹ یا نیٹ ورک سرگرمی (لاگ ڈیٹا)، تجارتی معلومات (رکنیت اور founding-seat ادائیگیاں)، اور صارف کی بنائی ہوئی مواد (آپ کا ورک اسپیس)۔ ذرائع: آپ، Clerk، اور Dodo Payments۔ جنہیں بتایا گیا: سیکشن 4 میں درج سروس فراہم کرنے والے۔ برقرار رکھنے کی مدت: سیکشن 6۔",
  "legal.privacy.ifYouLiveInAStateWithAComprehensiveConsumerPrivacyLawCal": "اگر آپ ایسی ریاست میں رہتے ہیں جہاں صارف کی رازداری کا جامع قانون ہے — California، Colorado، Connecticut، Virginia اور دوسری ریاستیں جنہوں نے ایسا قانون بنایا ہے — تو آپ کو وہ حقوق حاصل ہیں جو وہ ریاست دیتی ہے۔ California کے باشندوں کے لیے، CCPA کے تحت جیسا کہ CPRA نے ترمیم کیا، آپ کو یہ حق ہے کہ جان سکیں کہ ہم کون سی ذاتی معلومات اکٹھی کرتے، استعمال کرتے اور بتاتے ہیں؛ اسے حذف کریں؛ درست کریں؛ اس کی فروخت یا sharing سے opt out کریں؛ حساس ذاتی معلومات کا استعمال محدود کریں؛ اور ان حقوق کے استعمال پر امتیاز نہیں سہنا۔ ہم ذاتی معلومات نہیں بیچتے، کراس کنٹیکسٹ رویہ پر مبنی اشتہارات کے لیے شیئر نہیں کرتے، اور سروس دینے کے لیے ضروری سے زیادہ حساس ذاتی معلومات استعمال نہیں کرتے، اس لیے opt out کرنے کے لیے کچھ نہیں ہے، لیکن آپ ہم سے تصدیق ضرور کر سکتے ہیں۔",
  "legal.privacy.n13NoticeToUsStateResidents": "13. امریکی ریاستوں کے باشندوں کے لیے نوٹس",
  "legal.privacy.weMayNeedToVerifyYourIdentityAndWillAnswerWithinOneMonth": "؛ ہمیں آپ کی شناخت تصدیق کرنے کی ضرورت ہو سکتی ہے اور ہم ایک مہینے کے اندر جواب دیں گے، یا بتائیں گے کہ توسیع کیوں لاگو ہوتی ہے۔ آپ اپنے رہائشی ملک کی نگران اتھارٹی کے پاس بھی شکایت درج کر سکتے ہیں۔",
  "legal.privacy.youMayAskUsToGiveYouAccessToYourPersonalDataCorrectInacc": "آپ ہم سے اپنے ذاتی ڈیٹا تک رسائی، غلطیوں کی درستی، جہاں رکھنے کی کوئی جاری وجہ نہ ہو حذف کرنے، منتقلی کے لیے مشینی قابلِ پڑھ فارمیٹ میں دینے، ہماری پروسیسنگ کو محدود کرنے، یا جائز مفادات پر مبنی پروسیسنگ (بشمول براہِ راست مارکیٹنگ) پر اعتراض کرنے کو کہہ سکتے ہیں۔ جہاں ہم رضامندی پر انحصار کرتے ہیں، آپ اسے کسی بھی وقت واپس لے سکتے ہیں۔ کسی حق کو استعمال کرنے کے لیے، ای میل کریں",
  "legal.privacy.yourRights": "آپ کے حقوق۔",
  "legal.privacy.consentWhereYouChooseToConnectAnAiClientOrEnableAnOption": "رضامندی جب آپ AI کلائنٹ جوڑنے یا اختیاری ای میل آن کرنے کا انتخاب کرتے ہیں۔ آپ رضامندی کسی بھی وقت واپس لے سکتے ہیں؛ اس سے پہلے ہوئی پروسیسنگ متاثر نہیں ہوتی۔",
