  "legal.privacy.tahaAalamASoleProprietorTradingAsSophionosIsTheControlle": "Taha Aalam، SophionOS کے نام سے تجارت کرنے والے ایک تنہا مالک، اس پالیسی میں بیان کردہ پروسیسنگ کے controller ہیں۔ رابطہ:",
  "legal.privacy.controller": "Controller۔",
  "legal.privacy.thisSectionAppliesToYouIfYouAreInTheEuropeanEconomicArea": "یہ سیکشن آپ پر لاگو ہوتا ہے اگر آپ European Economic Area، United Kingdom، یا Switzerland میں ہیں (جنہیں اجتماعی طور پر \"Europe\" کہا گیا ہے)۔ یہاں \"Personal information\" کا مطلب EU GDPR یا UK GDPR کے مطابق \"personal data\" ہے۔ سروس یورپ میں قائم نہیں ہے؛ یہ نوٹس یورپی ڈیٹا تحفظ کے قانون کو اس حد تک پیش کرتا ہے جہاں یہ یورپ میں رہنے والوں کو سروس دینے پر لاگو ہوتا ہے۔",
