  "legal.privacy.n12NoticeToEuropeanUsers": "12. یورپی صارفین کے لیے نوٹس",
  "legal.privacy.weOperateTheServiceFromTheUnitedStatesAndUseServiceProvi": "ہم سروس امریکہ سے چلاتے ہیں اور امریکہ اور یورپی یونین میں سروس فراہم کرنے والوں کا استعمال کرتے ہیں۔ اس لیے آپ کی ذاتی معلومات آپ کی رہائشی جگہ سے باہر، ایسے ملک میں بھی پروسیس ہو سکتی ہیں جہاں رازداری کے قوانین آپ سے مختلف ہوں۔ جہاں GDPR لاگو ہوتا ہے، ہم ان منتقلیوں کے لیے مناسب حفاظتی اقدامات پر انحصار کرتے ہیں: standard contractual clauses، یا قابلِ اطلاق adequacy decision۔ جہاں بھارت کا DPDP Act لاگو ہوتا ہے، منتقلی DPDP Rules، 2025 کے Rule 15 کے تحت مرکزی حکومت کی مقررہ پابندیوں کے تابع ہوتی ہیں۔",
  "legal.privacy.n11InternationalDataTransfers": "11. بین الاقوامی ڈیٹا منتقلی",
