  "legal.privacy.noSystemIsPerfectlySecureSophionosIsSelfhostedWhoeverOpe": "کوئی نظام مکمل طور پر محفوظ نہیں۔ SophionOS خود میزبانی ہے: جو بھی کسی انسٹانس کو چلاتا ہے، اسے اسے محفوظ بنانے اور اپنے دائرے میں آنے والی breach-notification ذمہ داریاں پوری کرنے کی ذمہ داری حاصل ہے۔ دیکھیں",
