  "legal.privacy.sophionosIsALifeOperatingSystemAndSystemOfRecordForInter": "SophionOS باہم جڑے زندگی کے دائروں کے لیے ایک زندگی کا آپریٹنگ سسٹم اور ریکارڈ کا نظام ہے: علاقے، اہداف، منصوبے، کام، نوٹس، وسائل، موضوعات، اور رابطے۔ اس پالیسی میں، \"SophionOS\"، \"we\"، \"us\" سے مراد Taha Aalam ہیں، جو SophionOS کے نام سے تجارت کرنے والے ایک تنہا مالک ہیں اور SophionOS Cloud سروس چلاتے ہیں۔ \"You\" سے مراد اسے استعمال کرنے والا شخص ہے۔",
