  "legal.terms.thePurchaseOfAPaidPlanOrAFoundingCohortSeatIsASeparateCo": "ادائیگی والے پلان یا Founding Cohort نشست کی خریداری Dodo Payments کے ساتھ ایک الگ معاہدہ ہے، جو Dodo Payments کی شرائطِ فروخت میں درج قانون اور فورم کے تحت ہے۔",
