  "legal.terms.continuingToUseTheServiceAfterTheEffectiveDateOfARevised": "نئے ورژن کی نافذ العمل تاریخ کے بعد سروس استعمال جاری رکھنے کا مطلب ہے کہ آپ اسے قبول کرتے ہیں۔ جہاں تبدیلی قانون کے تقاضے سے یا سیکیورٹی خطرے کو دور کرنے کے لیے ہو، پرانے قبول شدہ ورژن کا استعمال جاری نہیں رکھا جا سکتا۔ قبولیت کے وقت نافذ ورژن اُس سے پہلے کی مدت کو کنٹرول کرتا ہے۔",
