  "legal.terms.exceptions": "استثناءات۔",
  "legal.terms.exceptAsStatedBelowYouAndSophionosAgreeToResolveEveryDis": "نیچے بتائے گئے کو چھوڑ کر، آپ اور SophionOS اس بات پر متفق ہیں کہ سروس یا ان شرائط سے پیدا ہونے والے یا ان سے متعلق ہر تنازعے کو پابند انفرادی ثالثی کے ذریعے حل کریں گے، عدالت میں نہیں۔ ثالثی ہماری تحریری رضامندی سے طے شدہ کسی تسلیم شدہ ثالثی فراہم کنندہ کے اصولوں کے تحت چلائی جائے گی؛ اگر ہم رضامند نہ ہو سکیں تو صارف تنازعات کے لیے American Arbitration Association's Consumer Arbitration Rules کے تحت۔ ثالثی کی نشست وہ کاؤنٹی ہے جہاں آپ رہتے ہیں، جب تک ہم دونوں کسی اور پر رضامند نہ ہوں۔",
  "legal.terms.agreementToArbitrate": "ثالثی کا معاہدہ۔",
  "legal.terms.withADescriptionOfTheDisputeAndTheReliefYouWantWeWillDoT": "تنازعے کی تفصیل اور آپ کی مطلوبہ ریلیف کے ساتھ۔ اگر ہمیں آپ سے تنازعہ ہو تو ہم بھی ایسا کریں گے۔ اگر 60 دن کے اندر حل نہ ہو تو ہم میں سے کوئی بھی ثالثی شروع کر سکتا ہے۔",
