  "legal.terms.pleaseReadThisSectionCarefullyItAffectsYourLegalRightsIn": "براہِ کرم یہ سیکشن غور سے پڑھیں۔ یہ آپ کے قانونی حقوق کو متاثر کرتا ہے، بشمول عدالت میں مقدمہ دائر کرنے اور جیوری ٹرائل کا حق۔",
  "legal.terms.n17DisputeResolutionAndArbitration": "17. تنازعات کا حل اور ثالثی",
  "legal.terms.youAgreeToDefendAndIndemnifySophionosAndItsContributorsA": "آپ اس بات سے متفق ہیں کہ ان شرائط کی آپ کی خلاف ورزی، کسی قانون کی خلاف ورزی، یا آپ کی دی گئی مواد سے کسی تیسرے فریق کے حقوق کی تجاوزت سے پیدا ہونے والے دعووں، مناسب اخراجات، اور وکیل کی فیسوں کے خلاف آپ SophionOS اور اس کے معاونین کا دفاع اور معاوضہ کریں گے۔ ہم ایسے کسی بھی دعوے کا دفاع آپ کی لاگت پر سنبھال سکتے ہیں، اور آپ ہماری تحریری رضامندی کے بغیر ایسا دعویٰ طے نہیں کریں گے۔",
  "legal.terms.n16Indemnity": "16. معاوضہ",
  "legal.terms.nothingInTheseTermsExcludesLiabilityThatCannotLawfullyBe": "ان شرائط میں کچھ بھی ایسی ذمہ داری خارج نہیں کرتا جسے قانوناً خارج نہیں کیا جا سکتا، بشمول دھوکہ یا جان بوجھ کر غلط کام کی ذمہ داری۔",
  "legal.terms.toTheMaximumExtentPermittedByLawWeAreNotLiableForIndirec": "قانون کی اجازت کی زیادہ سے زیادہ حد تک، ہم سروس سے پیدا ہونے والے یا اس سے متعلق بالواسطہ، حادثاتی، خصوصی، نتیجہ خیز، یا سزائی والے نقصانات، یا منافع، آمدنی، یا ڈیٹا کے ضیاع کے لیے ذمہ دار نہیں ہیں۔ کسی بھی بارہ ماہ کی مدت میں ہماری کل ذمہ داری اُس رقم اور INR 10,000 میں سے زیادہ تک محدود ہے جو آپ نے اس مدت میں ہمیں سروس کے لیے دی تھی۔",
  "legal.terms.n15LimitationOfLiability": "15. ذمہ داری کی حد",
  "legal.terms.thereHasBeenNoFormalThirdpartySecurityAuditOfThisCodebas": "اس کوڈ بیس کا کوئی باقاعدہ تھیرڈ پارٹی سیکیورٹی آڈٹ نہیں ہوا؛ API/MCP سطح تجرباتی ہے، اور باقی خطرات (پرامپٹ انجیکشن، آپ کی اجازت سے کلائنٹ کے ذریعے ڈیٹا نکالنا، آپریٹر کو نظر آنے والے سروس ڈیٹا) باقی ہیں۔ اہم، طبی، قانونی، یا حفاظتی لحاظ سے نازک معلومات کے لیے SophionOS کو واحد ذخیرہ نہ سمجھیں۔ جہاں قانون وارنٹی کا تقاضا کرتا ہے، وہ پہلے استعمال سے 90 دن تک محدود ہے۔ یہاں کچھ بھی موت، جسمانی چوٹ، دھوکہ، یا کسی اور چیز کی ذمہ داری خارج نہیں کرتا جسے قانون خارج نہیں کرنے دیتا۔",
  "legal.terms.toTheMaximumExtentPermittedByLawWeDisclaimAllWarrantiesE": "قانون کی اجازت کی زیادہ سے زیادہ حد تک، ہم تمام وارنٹیاں، صریح یا ضمنی، بشمول قابلِ فروخت ہونا، کسی خاص مقصد کے لیے موزوں ہونا، ملکیت، اور تجاوز نہ کرنا، خارج کرتے ہیں۔ ہم ضمانت نہیں دیتے کہ سروس بلا رکاوٹ، محفوظ، یا بے ترازی ہوگی۔",
  "legal.terms.n14Disclaimers": "14. دستبرداریاں",
  "legal.terms.theseTermsGovernYourUseOfSophionosCloudTheUnderlyingCode": "یہ شرائط SophionOS Cloud کے آپ کے استعمال کو کنٹرول کرتی ہیں۔ بنیادی کوڈ، SophionOS Core، AGPL-3.0-or-later کے تحت اوپن سورس ہے۔ اگر آپ خود میزبانی کرتے ہیں تو آپ اس تعیناتی کے آپریٹر ہیں: processors، خطے، بیک اپ، TLS، برقرار رکھنے کی مدت، اور قانونی بنیاد آپ منتخب کرتے ہیں، اور ان شرائط کی Cloud سے متعلق تفصیلات (پلان، بلنگ، میزبان ذیلی processors) آپ کی تعیناتی پر لاگو نہیں ہوتیں۔ جب تک کوئی تعیناتی واقعی کسی نیٹ ورک شناساگر، میزبان ڈیٹا بیس، یا دور دراز AI کلائنٹ استعمال نہ کرے، اسے \"ڈیٹا کبھی ڈیوائس سے باہر نہیں جاتا\" نہ کہیں۔",
  "legal.terms.n13SelfhostedSophionosCoreVsSophionosCloud": "13. خود میزبانی SophionOS Core بمقابلہ SophionOS Cloud",
  "legal.terms.dodoPaymentsIsNotInThatListBecauseItIsNotAServiceWeInteg": "Dodo Payments اس فہرست میں نہیں، کیونکہ یہ کوئی ایسی سروس نہیں ہے جسے ہم آپ کی طرف سے مربوط کریں: یہ ہمارا merchant of record اور ادائیگی والے پلانوں و founding نشستوں کا seller of record ہے (سیکشن 1)۔ Dodo Payments طے کرتا ہے کہ آپ کے ادائیگی کے ڈیٹا کو کیسے پروسیس کیا جائے، اور اس پر Dodo Payments کی اپنی پرائیویسی پالیسی لاگو ہوتی ہے۔",
