  "legal.terms.whereA14dayRightOfWithdrawalAppliesToADigitalSubscriptio": "جہاں ڈیجیٹل رکنیت پر 14 دن کے اندر انخلا کا حق لاگو ہوتا ہے، آپ خریداری کے 14 دن کے اندر انخلا کر سکتے ہیں۔ Founding-seat کی خریداری سیکشن 4 کے تحت ہے۔",
