  "legal.terms.within60DaysOfTheChargeAndWeWillRefundTheErroneousCharge": "چارج کے 60 دن کے اندر اور ہم غلط چارج واپس کریں گے۔ Dodo Payments، merchant of record کی حیثیت سے، واپسی اصل ادائیگی کے طریقے پر جاری کرتا ہے۔",
  "legal.terms.ifYouAreChargedInErrorIncludingBeingChargedTwiceForTheSa": "اگر آپ سے غلطی سے چارج کیا جائے، بشمول ایک ہی مدت کے لیے دو بار چارج کیا جائے، تو لکھیں",
