  "legal.terms.ifPaymentFailsAndIsNotResolvedWithinTheGracePeriodShownI": "اگر ادائیگی ناکام ہو اور ایپ میں دکھائی گئی مہلت کے اندر حل نہ ہو تو اکاؤنٹ Free ٹیئر پر چلا جاتا ہے اور ادائیگی والی خصوصیات معطل ہو جاتی ہیں؛",
