  "legal.dataAndAi.andTurnOnAiSummariesInSettingsNotificationsWhenASchedule": "اور ترتیبات → اطلاعات میں AI خلاصے آن کریں۔ جب کوئی شیڈول شدہ بریف وقت پر ہو اور یہ آن ہو، تو SophionOS آپ کے منتخب فراہم کنندہ کو ایک درخواست بھیجتا ہے جس میں ویسا ہی ڈیٹا ہوتا ہے جو ای میل بریف پہلے ہی رکھتا ہے — اعداد کی گنتی، سرفہرست کام کے عنوانات، اور اہداف کے عنوانات پیش رفت کے ساتھ۔ کچھ اور نہیں بھیجا جاتا، کوئی اور خصوصیت ماڈل کو کال نہیں کرتی، اور اگر فراہم کنندہ دستیاب نہ ہو تو معیاری بریف بھیجی جاتی ہے۔",
